const body = $node["Webhook"].json.body;

const cleanText = (value, maxLength = 500) => {
  if (value === null || value === undefined) return null;

  return String(value)
    .replace(/<[^>]*>/g, "")
    .replace(/[\u0000-\u001F\u007F]/g, "")
    .trim()
    .replace(/\s+/g, " ")
    .slice(0, maxLength);
};

const cleanEmail = body.email
  ? String(body.email).trim().toLowerCase()
  : null;

const cleanPhone = body.phone
  ? String(body.phone).replace(/[^\d+]/g, "")
  : null;

return {
  raw_lead_id: $json.id,
  sanitized: {
    source: cleanText(body.source, 100),
    source_lead_id: cleanText(body.source_lead_id, 100),
    full_name: cleanText(body.full_name, 150),
    email: cleanEmail,
    phone: cleanPhone,
    lead_type: cleanText(body.lead_type, 50),
    location: cleanText(body.location, 150),
    budget: body.budget ?? null,
    timeline: cleanText(body.timeline, 100),
    message: cleanText(body.message, 1000),
    email_consent: typeof body.email_consent === "boolean" ? body.email_consent : null,
    sms_consent: typeof body.sms_consent === "boolean" ? body.sms_consent : null
  }
};

const lead = $json.sanitized;
const errors = [];

const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const phoneRegex = /^\+\d{8,15}$/;

const hasValidEmail =
  Boolean(lead.email) && emailRegex.test(lead.email);

const hasValidPhone =
  Boolean(lead.phone) && phoneRegex.test(lead.phone);

if (!lead.source) {
  errors.push('source_missing');
}

if (!lead.source_lead_id) {
  errors.push('source_lead_id_missing');
}

if (!hasValidEmail && !hasValidPhone) {
  errors.push('no_valid_contact_method');
}

if (!lead.lead_type) {
  errors.push('lead_type_missing');
}

if (typeof lead.email_consent !== 'boolean') {
  errors.push('email_consent_missing');
}

if (typeof lead.sms_consent !== 'boolean') {
  errors.push('sms_consent_missing');
}

return {
  ...$json,
  validation: {
    is_valid: errors.length === 0,
    errors,
    has_valid_email: hasValidEmail,
    has_valid_phone: hasValidPhone
  }
};

const data = $json.sanitized ?? {};

function normalizeBudget(value) {
  if (value === null || value === undefined || value === '') {
    return null;
  }

  if (typeof value === 'number') {
    return Math.round(value);
  }

  const original = String(value).trim().toLowerCase();

  if (!original) {
    return null;
  }

  let multiplier = 1;

  if (
    original.includes('million') ||
    original.includes('millions') ||
    /\d(?:[.,]\d+)?\s*m\b/.test(original)
  ) {
    multiplier = 1_000_000;
  } else if (
    original.includes('thousand') ||
    original.includes('mille') ||
    /\d(?:[.,]\d+)?\s*k\b/.test(original)
  ) {
    multiplier = 1_000;
  }

  let cleaned = original
    .replace(/mad|dhs?|dirhams?|million[s]?|mille|thousand/gi, '')
    .replace(/[mk]/gi, '')
    .replace(/\s+/g, '')
    .trim();

  if (!cleaned) {
    return null;
  }

  if (multiplier > 1) {
    cleaned = cleaned.replace(',', '.');
  } else {
    cleaned = cleaned.replace(/[.,]/g, '');
  }

  const amount = Number.parseFloat(cleaned);

  if (!Number.isFinite(amount) || amount <= 0) {
    return null;
  }

  return Math.round(amount * multiplier);
}

function normalizeLocation(value) {
  if (!value) {
    return null;
  }

  const original = String(value).trim();

  const normalizedKey = original
    .toLowerCase()
    .replace(/\s+/g, ' ');

  const aliases = {
    casa: 'Casablanca',
    casablanca: 'Casablanca',
    'casa blanca': 'Casablanca',

    rabat: 'Rabat',

    marrakech: 'Marrakech',
    marrakesh: 'Marrakech',

    tangier: 'Tangier',
    tanger: 'Tangier',

    bouskoura: 'Bouskoura',

    darbouazza: 'Dar Bouazza',
    'dar bouazza': 'Dar Bouazza',

    mohammedia: 'Mohammedia',
    agadir: 'Agadir',

    fes: 'Fes',
    fez: 'Fes'
  };

  return aliases[normalizedKey] ?? original;
}

function determineUrgency(value) {
  if (!value) {
    return 'unknown';
  }

  const timeline = String(value).trim().toLowerCase();

  const highUrgencyTerms = [
    'asap',
    'immediately',
    'urgent',
    'today',
    'this week',
    'within a week',
    'before the end of the month'
  ];

  const mediumUrgencyTerms = [
    'this month',
    'next month',
    '1 month',
    '2 months',
    '3 months',
    'within 3 months'
  ];

  const lowUrgencyTerms = [
    'later',
    'not urgent',
    'just looking',
    'exploring',
    '6 months',
    'next year'
  ];

  if (highUrgencyTerms.some(term => timeline.includes(term))) {
    return 'high';
  }

  if (mediumUrgencyTerms.some(term => timeline.includes(term))) {
    return 'medium';
  }

  if (lowUrgencyTerms.some(term => timeline.includes(term))) {
    return 'low';
  }

  return 'unknown';
}

function categorizeBudget(amount) {
  if (!amount) {
    return 'unknown';
  }

  if (amount < 800_000) {
    return 'entry';
  }

  if (amount < 1_500_000) {
    return 'mid_market';
  }

  if (amount < 3_000_000) {
    return 'premium';
  }

  return 'luxury';
}

const startedAt = Date.now();

const budgetNormalized = normalizeBudget(data.budget);

const rules = {
  budget_normalized: budgetNormalized,
  budget_currency: budgetNormalized ? 'MAD' : null,
  budget_category: categorizeBudget(budgetNormalized),
  location_normalized: normalizeLocation(data.location),
  urgency: determineUrgency(data.timeline)
};

return {
  json: {
    ...$json,
    enrichment: {
      rules,
      ai: null,
      metadata: {
        version: '1.0',
        method: 'rules',
        processed_at: new Date().toISOString(),
        processing_time_ms: Date.now() - startedAt
      }
    }
  }
};

const sanitized = $('Sanitize Lead').item.json.sanitized ?? {};
const enrichment =
  $('Rules Enrichment').item.json.enrichment ??
  {};

const rules = enrichment.rules ?? {};

function formatBudget(amount, currency = 'MAD') {
  if (!amount || !Number.isFinite(Number(amount))) {
    return 'Not provided';
  }

  const value = Number(amount);

  if (value >= 1_000_000) {
    const millions = value / 1_000_000;

    return `${millions.toFixed(
      Number.isInteger(millions) ? 0 : 1
    )}M ${currency}`;
  }

  if (value >= 1_000) {
    return `${Math.round(value / 1_000)}K ${currency}`;
  }

  return `${value.toLocaleString('en-US')} ${currency}`;
}

function getRecommendedAction(urgency, budgetCategory) {
  if (urgency === 'high') {
    return 'Call within 15 minutes';
  }

  if (budgetCategory === 'luxury') {
    return 'Assign to a senior sales agent';
  }

  if (budgetCategory === 'premium') {
    return 'Contact within 1 hour';
  }

  return 'Review and follow up';
}

const priority =
  rules.urgency === 'high' || rules.budget_category === 'luxury'
    ? 'HIGH'
    : 'MEDIUM';

const notification = {
  type: 'new_lead_alert',
  title: 'High-Priority Real Estate Lead',
  priority,

  lead: {
    full_name: sanitized.full_name ?? 'Unknown',
    email: sanitized.email ?? null,
    phone: sanitized.phone ?? null,
    lead_type: sanitized.lead_type ?? 'unknown',
    location:
      rules.location_normalized ??
      sanitized.location ??
      'Not provided',
    budget: formatBudget(
      rules.budget_normalized,
      rules.budget_currency ?? 'MAD'
    ),
    budget_category: rules.budget_category ?? 'unknown',
    urgency: rules.urgency ?? 'unknown',
    message: sanitized.message ?? null
  },

  recommended_action: getRecommendedAction(
    rules.urgency,
    rules.budget_category
  ),

  metadata: {
    raw_lead_id:
      $('Store Raw Lead').item.json.raw_lead_id ??
      $('Sanitize Lead').item.json.raw_lead_id ??
      null,
    source: sanitized.source ?? null,
    source_lead_id: sanitized.source_lead_id ?? null,
    generated_at: new Date().toISOString()
  }
};

return {
  json: {
    ...$json,
    notification
  }
};

